'use strict';
const { test } = require('node:test');
const assert = require('node:assert/strict');
const fs = require('node:fs');
const os = require('node:os');
const path = require('node:path');
const { Pool } = require('pg');
const state = require('../../src/lib/messageCounterStore');
const { initializeCounters } = require('../../src/DB/Initialization/messageCounters');
const { initializeRoulette } = require('../../src/DB/Initialization/roulette');
const { createRouletteStore } = require('../../src/lib/rouletteStore');

test('PostgreSQL migration, concurrency, persistence and command behavior', { skip: !process.env.COUNTER_TEST_DB }, async () => {
  require('dotenv').config();
  const connection = { host: process.env.COUNTER_TEST_HOST || '127.0.0.1', port: Number(process.env.DB_PORT || 5432), user: process.env.DB_USER, password: process.env.DB_PASSWORD, database: process.env.DB_NAME };
  const admin = new Pool(connection);
  const schema = `counter_test_${process.pid}_${Date.now()}`;
  await admin.query(`CREATE SCHEMA ${schema}`);
  const pool = new Pool({ ...connection, options: `-c search_path=${schema}`, max: 5 });
  const dir = fs.mkdtempSync(path.join(os.tmpdir(), 'message-counters-'));
  const counterFile = path.join(dir, 'counts.json');
  const store = state.createCounterStore(pool, counterFile);
  const original = { get: state.get, increment: state.increment };
  state.get = store.get; state.increment = store.increment;
  try {
    fs.writeFileSync(counterFile, JSON.stringify({ zuh: -1 }));
    await assert.rejects(initializeCounters(pool, counterFile), /Invalid message counter/);
    const rolledBack = await pool.query("SELECT to_regclass('message_counters') AS table_name");
    assert.equal(rolledBack.rows[0].table_name, null);
    fs.writeFileSync(counterFile, JSON.stringify({ zuh: 10, '67': 20 }));
    await initializeCounters(pool, counterFile);
    fs.writeFileSync(counterFile, 'invalid old backup');
    const { createMessageHandler } = require('../../src/lib/messageHandler');
    const commands = new Map(['67', 'zuh'].map(name => [name, require(`../../src/commands/${name}`)]));
    let regular = 0;
    commands.set('test', { name: 'test', execute: async ({ args }) => { regular++; assert.deepEqual(args, ['67']); } });
    const replies = [];
    const handler = createMessageHandler({ commands, client: { say: async (channel, text) => replies.push(text) }, prefix: '!', logger: { info() {}, error(err) { throw new Error(err); } } });
    const send = (text, self = false) => handler('channel', { username: 'viewer' }, text, self);
    await send('67 zuh', true);
    await send('nothing here');
    assert.equal(replies.length, 0);
    await send('!zuh');
    assert.deepEqual(replies.splice(0), ['10 zuh .']);
    await send('abc167xyz 67 ZUHahaha zuh');
    assert.deepEqual(replies.splice(0), ['This ABERRATION of a number has been said 21 times']);
    await send('!67');
    assert.deepEqual(replies.splice(0), []);
    await send('!ZUH');
    assert.deepEqual(replies.splice(0), ['11 zuh .']);
    await send('zuh');
    assert.equal(replies.length, 0);
    await send('!test 67');
    assert.equal(regular, 1);
    const replyCount = replies.length;
    await Promise.all(Array.from({ length: 20 }, () => send('67')));
    assert.equal(await store.get('67'), 43);
    assert.equal(await store.get('zuh'), 12);
    assert.equal(replies.length, replyCount);
    const restarted = state.createCounterStore(pool, counterFile);
    await initializeCounters(pool, counterFile);
    assert.equal(await restarted.increment('zuh'), 13);
    assert.equal(await store.get('zuh'), 13);
    const results = await Promise.all(Array.from({ length: 30 }, () => restarted.increment('67')));
    assert.equal(new Set(results).size, 30);
    assert.equal(await store.get('67'), 73);
    await initializeRoulette(pool);
    const roulette = createRouletteStore(pool);
    assert.deepEqual(await roulette.leaderboard(), []);
    await Promise.all(Array.from({ length: 20 }, () => roulette.increment('Viewer')));
    await roulette.increment('Other');
    const newRoulette = createRouletteStore(pool);
    assert.deepEqual(await newRoulette.leaderboard(), [{ username: 'viewer', count: 20 }, { username: 'other', count: 1 }]);
    await initializeRoulette(pool);
    assert.equal((await newRoulette.leaderboard())[0].count, 20);
    await assert.rejects(pool.query("UPDATE message_counters SET count = -1 WHERE name = 'zuh'"), /check constraint/);
  } finally {
    Object.assign(state, original);
    await pool.end();
    await admin.query(`DROP SCHEMA ${schema} CASCADE`);
    await admin.end();
    fs.rmSync(dir, { recursive: true, force: true });
  }
});
